})
export class SubjectListComponent {
  @Input() initialized: boolean;
  @Input() subjects: Subject[];

  constructor(private readonly _stateService: KdStateService) {}

  getColumns(): string[] {
    return ['name', 'namespace', 'kind', 'apiGroup'];
  }

  getDataSource(): MatTableDataSource<Subject> {
    const tableData = new MatTableDataSource<Subject>();
    tableData.data = this.subjects;
    return tableData;
