    const knownKinds = [Resource.serviceAccount.toString()];
    return knownKinds.includes(subject.kind.toLowerCase());
  }

  getSubjectHref(subject: Subject): string {
    return this._stateService.href(subject.kind.toLowerCase(), subject.name, subject.namespace);
  }
}

