    this.opened
      .pipe(takeUntil(this.unsubscribe_))
      .subscribe(opened => (opened ? setTimeout(() => this._el.nativeElement.focus()) : null));
  }

  ngOnDestroy(): void {
    this.unsubscribe_.next();
    this.unsubscribe_.complete();
  }
}

