export class AzureDiskVolumeSource implements IVolumeSource {
  diskName: string;
  dataDiskURI: string;
  cachingMode: AzureDataDiskCachingMode;
  fsType: string;
  readOnly: boolean;
  kind: AzureDataDiskKind;

  get mountType(): string {
    return 'Azure Disk';
  }

  get displayName(): string {
    return this.diskName;
  }
}

